/*
 * Fixed-Capacity String - Internal Implementation
 *
 * Raw functions that operate on (char *data, size_t *len, size_t capacity).
 * Type-safe wrappers are generated by the IEC61850_DEFINE_FIXED_STRING macro.
 */

#include "containers/fixed_string.h"
#include <string.h>

/*@ requires \valid(data);
  @ requires \valid(len);
  @ assigns data[0], *len;
  @ ensures data[0] == '\0';
  @ ensures *len == 0;
  @*/
void iec61850_fixed_string_init_raw(char *data, size_t *len)
{
    data[0] = '\0';
    *len = 0;
}

/*@ requires \valid(data + (0..capacity));
  @ requires \valid(len);
  @ requires capacity > 0;
  @ assigns data[0..capacity], *len;
  @ ensures \result == 0;
  @ ensures data[*len] == '\0';
  @ ensures *len <= capacity;
  @*/
int iec61850_fixed_string_assign_raw(char *data, size_t *len, size_t capacity,
                                      const char *str)
{
    if (str == NULL) {
        data[0] = '\0';
        *len = 0;
    } else {
        size_t slen = strlen(str);
        if (slen > capacity) {
            slen = capacity;
        }
        (void)memcpy(data, str, slen);
        data[slen] = '\0';
        *len = slen;
    }

    return 0;
}

/*@ requires \valid(data + (0..capacity));
  @ requires \valid(len);
  @ requires capacity > 0;
  @ requires \valid_read(str + (0..n-1));
  @ assigns data[0..capacity], *len;
  @ ensures \result == 0;
  @ ensures data[*len] == '\0';
  @ ensures *len <= capacity;
  @ ensures *len <= n;
  @*/
int iec61850_fixed_string_assign_n_raw(char *data, size_t *len, size_t capacity,
                                        const char *str, size_t n)
{
    if (str == NULL) {
        data[0] = '\0';
        *len = 0;
    } else {
        size_t copy_len = n;
        if (copy_len > capacity) {
            copy_len = capacity;
        }
        (void)memcpy(data, str, copy_len);
        data[copy_len] = '\0';
        *len = copy_len;
    }

    return 0;
}

/*@ requires \valid(data);
  @ requires \valid(len);
  @ assigns data[0], *len;
  @ ensures data[0] == '\0';
  @ ensures *len == 0;
  @*/
void iec61850_fixed_string_clear_raw(char *data, size_t *len)
{
    data[0] = '\0';
    *len = 0;
}

/*@ requires \valid_read(data1 + (0..len1-1));
  @ requires \valid_read(data2 + (0..len2-1));
  @ assigns \nothing;
  @*/
bool iec61850_fixed_string_equal_raw(const char *data1, size_t len1,
                                      const char *data2, size_t len2)
{
    bool result;
    if (len1 != len2) {
        result = false;
    } else {
        result = (memcmp(data1, data2, len1) == 0);
    }
    return result;
}

/*@ requires \valid_read(data1 + (0..len1));
  @ requires \valid_read(data2 + (0..len2));
  @ assigns \nothing;
  @*/
int iec61850_fixed_string_compare_raw(const char *data1, size_t len1,
                                       const char *data2, size_t len2)
{
    size_t min_len = (len1 < len2) ? len1 : len2;
    int result = memcmp(data1, data2, min_len);
    if (result == 0) {
        if (len1 < len2) {
            result = -1;
        } else if (len1 > len2) {
            result = 1;
        } else {
            /* equal lengths — result stays 0 */
        }
    }
    return result;
}

/*@ requires \valid_read(data + (0..len));
  @ assigns \nothing;
  @*/
bool iec61850_fixed_string_equal_cstr_raw(const char *data, size_t len,
                                           const char *cstr)
{
    bool result;
    if (cstr == NULL) {
        result = (len == 0U);
    } else {
        size_t clen = strlen(cstr);
        if (len != clen) {
            result = false;
        } else {
            result = (memcmp(data, cstr, len) == 0);
        }
    }
    return result;
}
